import{_ as a,o as i,c as n,a4 as e}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20240531235823670.ByOADPO8.png",l="/assets/image-20240531230947783.OsZsv1zP.png",p="/assets/image-20240531231710994.CCdtYwrZ.png",r="/assets/image-20240531231342832.Dzod0uwR.png",o="/assets/image-20240531232324089.KVAr_qXu.png",h="/assets/image-20240531232826263.N86_Wsoq.png",g="/assets/image-20240531233143803.UW6gCpf4.png",c="/assets/image-20240531233422423.CjYMyzUy.png",d="/assets/image-20240531233719248.CtFMixfR.png",k="/assets/image-20240531234536893.BkMh6b4s.png",q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙编辑器调试技巧/鸿蒙编辑器调试技巧.md","filePath":"鸿蒙开发技巧/鸿蒙编辑器调试技巧/鸿蒙编辑器调试技巧.md","lastUpdated":1758030697000,"__rawMarkdown":"## 最新 HUAWEI DevEco Studio 调试技巧\\n\\n## 前言\\n\\n![image-20240531235823670](readme.assets/image-20240531235823670.png)\\n\\n在我们使用 **HUAWEI DevEco Studio**  编辑器开发鸿蒙应用时，免不了要对我们的应用程序进行代码调试。我们根据实际情况，一般会用到以下几种方式进行代码调试。\\n\\n1.  肉眼调试法\\n2.  注释排错调试法\\n3.  try-catch\\n4.  控制台输出法\\n5.  弹出提示法\\n6.  **断点调试法**\\n\\n## 肉眼调试法\\n\\n**肉眼调试法**也称为**随缘调试法**，一般适用于编辑器有明显错误、或者是刚写完的小段代码中，明显依赖自己的**钛合金狗眼**。当你刚刚写好的一两行代码，运行发现出错时，就可以直接肉眼排错。如\\n\\n![image-20240531230947783](readme.assets/image-20240531230947783.png)\\n\\n**肉眼调试法** 也有很明显的弊端，如果是调试大段程序、或者调试别人的程序。那么此法就不可行了。如：\\n\\n![image-20240531231710994](readme.assets/image-20240531231710994.png)\\n\\n\\n\\n## 注释排错调试法\\n\\n**注释排错调试法**一般适用于没有明显的错误，自我感觉莫名其妙导致就出错的情况。如**代码昨天运行的时候还是好好，今天过来突然就不行了**。这个时候，可以大胆的根据代码流程来锁定可能出错的范围，将它注视掉。如果此时程序没有出错，那么就表示锁定出错的范围了。然后继续不断注释其他的，继续缩小范围，继续找到出错的可疑的代码，再进行调错。\\n\\n![image-20240531231342832](readme.assets/image-20240531231342832.png)\\n\\n## 控制台输出法\\n\\n**控制台输出法**，是程序员最拿手的调试法。直接在控制台中输出自己想要查看的数据，便捷快速。\\n\\n![image-20240531232324089](readme.assets/image-20240531232324089.png)\\n\\n但是在 **HUAWEI DevEco Studio**中。控制台的输入也有弊端：\\n\\n1. `console.log`的第一个参数必须时字符串\\n2. 无法有效的输出对象类型的数据。\\n\\n![image-20240531232826263](readme.assets/image-20240531232826263.png)\\n\\n因此对于对象类型的数据，一般可以通过序列化后再输出\\n\\n```ts\\nconsole.log(\\"二师兄\\", JSON.stringify(pug))\\n```\\n\\n**Tips：**如果是对象数组，可以使用 `console.table` 来友好的进行输出\\n\\n![image-20240531233143803](readme.assets/image-20240531233143803.png)\\n\\n\\n## try-catch\\n另外有一些程序可能在运行的时候会导致程序成直接崩溃，也没有太多错误提示，这个时候我们可以使用 try-catch 来捕获和输出错误\\n\\n```ts\\nonPageShow() {\\n  try {\\n    const list: number[] = []\\n    const a = list[1] + list[2]\\n    console.log(\\"成功输出\\", a)\\n  } catch (e) {\\n    console.log(\\"错误信息\\", e.message, e.code)\\n  }\\n}\\n```\\n\\n## 弹出提示法\\n\\n进行真机调试时，可以直接利用  `harmonyos`中提供的弹出窗口的方式 进行输出想要查看的数据\\n\\n1. `promptAction.showToast({ message: \\"黎猴呀\\" })`\\n2. `AlertDialog.show({ message: \\"执返剂\\" })`\\n\\n![image-20240531233422423](readme.assets/image-20240531233422423.png)\\n\\n---\\n\\n![image-20240531233719248](readme.assets/image-20240531233719248.png)\\n\\n## 断点调试法\\n\\n如果上述的方案都解决不了你调试bug的需求，那么最后一种你就一定要拿捏住。 该方式主要是利用了  **HUAWEI DevEco Studio**种提供的断点调试方式来进行。\\n\\n![image-20240531234536893](readme.assets/image-20240531234536893.png)\\n\\n\\n\\n\\n\\n## 结束\\n\\n如果可以帮助到你，欢迎来撩\\n\\n1. 邮箱  `yeah126139163@163.com`\\n2. 微信  `w846903522`\\n3. [掘金](https://juejin.cn/user/4441682708283191) \\n4. [b站](https://space.bilibili.com/414874315?spm_id_from=333.1007.0.0)\\n5. 公众号  `HarmonyOS 万少`"}'),m={name:"鸿蒙开发技巧/鸿蒙编辑器调试技巧/鸿蒙编辑器调试技巧.md"};function E(u,s,y,b,_,F){return i(),n("div",null,[...s[0]||(s[0]=[e("",38)])])}const v=a(m,[["render",E]]);export{q as __pageData,v as default};
